import{_ as e,o as r,c as a,ag as o}from"./chunks/framework.CZxGLIO_.js";const p=JSON.parse('{"title":"Rooster","description":"Rooster 安装、使用和维护指南。","frontmatter":{"title":"Rooster","description":"Rooster 安装、使用和维护指南。"},"headers":[],"relativePath":"docs/rooster/index.md","filePath":"docs/rooster/index.md"}'),d={name:"docs/rooster/index.md"};function n(s,t,c,i,h,l){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="rooster" tabindex="-1">Rooster <a class="header-anchor" href="#rooster" aria-label="Permalink to &quot;Rooster&quot;">​</a></h1><p>Rooster 将本地 Web 控制台、原生托盘、SQLite 执行历史与进程管理结合起来，适合开发服务、后台工作进程和定时脚本，也可由本地 Agent 通过 HTTP API 操作。</p><p>核对版本为 2026-11-15 的提交 <strong>96c86ae</strong>。截至此日期尚无 GitHub Release；旧源码构建可能缺少备份和清理接口，以运行实例的 <code>/api/docs</code> 为准。</p><h2 id="阅读顺序" tabindex="-1">阅读顺序 <a class="header-anchor" href="#阅读顺序" aria-label="Permalink to &quot;阅读顺序&quot;">​</a></h2><p>先安装并创建停用的 <code>echo ready</code> 任务，手动运行，检查执行历史与日志，再启用自动运行并建立备份。服务没有远程认证层，应保持本机访问。</p><table tabindex="0"><thead><tr><th>指南</th><th>内容</th></tr></thead><tbody><tr><td><a href="./installation/">安装与运行</a></td><td>后台、托盘、打包与独立数据目录</td></tr><tr><td><a href="./tasks/">任务配置与执行</a></td><td>命令模式、Cron、重启策略与并发</td></tr><tr><td><a href="./agent-api/">Agent 与 HTTP API</a></td><td>创建、运行、查询结果与错误处理</td></tr><tr><td><a href="./maintenance/">备份、恢复与日志</a></td><td>在线快照、离线恢复、日志与清理</td></tr><tr><td><a href="./troubleshooting/">故障排查</a></td><td>端口、环境、任务状态和恢复问题</td></tr></tbody></table><hr><p>核对日期：2026-11-15；依据当前源码：<a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/README.md" target="_blank" rel="noreferrer">README</a> · <a href="https://github.com/leancodebox/rooster/blob/96c86ae62c530da51cd6cd0f7b37b3d6fb7e89be/internal/httpapi/agent/references/api.md" target="_blank" rel="noreferrer">API</a>。</p>',8)])])}const f=e(d,[["render",n]]);export{p as __pageData,f as default};
